import React, { useRef } from "react";
import Animated, { ZoomInEasyDown } from "react-native-reanimated";
import { Text, View, useWindowDimensions, Platform } from "react-native";
import LottieView from 'lottie-react-native'
import { useScale } from "../../../hooks/utils/useScale";

const Game3TextAnimation = ({ text, thinking }) => {
    const { height: windowHeight, width: windowWidth } = useWindowDimensions();
    const animationRef = useRef(null);

    const { s, vs } = useScale()

    const Lottie = () => {
        return (
            <LottieView
                ref={animationRef}
                source={require('../../../../assets/loading.json')} 
                loop
                autoPlay
                style={{width: s(20), height: s(20), alignSelf: 'center'}}
            />
        )
    }

    return (
        <Animated.View key={text} entering={ZoomInEasyDown}
            style={{
                maxWidth: s(135),
                width: !thinking || text? 'auto' : windowWidth * (130 / 800),
                height: 'auto',
                backgroundColor: thinking? '#C4DF84' : text? '#C4DF84' : 'transparent',
                borderTopRightRadius: 16,
                borderTopLeftRadius: 16,
                borderBottomRightRadius: 16,
                padding: Platform.isPad? windowWidth * (12 / 800) : windowHeight * (12 / 360),
                marginLeft: s(3),
                marginBottom: s(15),
            }}
        >
            {!thinking || text? 
                <Text style={{ fontWeight: '400', fontSize: s(6), lineHeight: s(9), color: '#222222'}}>
                    {text}
                </Text>
            :
                <Lottie />
            }

            <View style={{
                width: 0,
                height: 0,
                borderRightWidth: 16,     // Ширина треугольника (основание)
                borderTopWidth: 8,        // Высота треугольника
                borderRightColor: 'transparent',
                borderTopColor: thinking? '#C4DF84' : text? '#C4DF84' : 'transparent',   // Цвет треугольника
                borderLeftWidth: 0,
                borderBottomWidth: 0,
                position: 'absolute',
                bottom: -8,
                left: 0
            }} />

        </Animated.View>
    );
}

export default Game3TextAnimation;