import { useState, useRef, useEffect } from 'react';
import { View, Vibration } from 'react-native';
import MicroAnimation from './Game1/MicroAnimation';
import TaskComponent from './Game1/TaskComponent';
import store from '../../store/store';
import useTimer from '../../hooks/utils/useTimer';
import { playSound } from '../../hooks/usePlaySound';
import { useIntroSequence } from '../../hooks/useIntroSequence';
import OverlayHint from './components/OverlayHint';
import SkipButton from './components/SkipButton';
import TutorialOverlay from './components/TutorialOverlay';
import WisyHint from './components/WisyHint';
import { AnswerVoiceTask } from '../../api/methods/game/answer';
import { GetSpeeches } from '../../api/methods/speeches/speech';
import { gameStore } from './store/gameStore';

const Game1Screen = ({ data, setLevel, setStars, onCompleteTask, subCollectionId, isFromAttributes, setEarnedStars, introAudio, introText, introTaskIndex, level, tutorials, tutorialShow, setTutorialShow }) => {    

    const [text, setText] = useState(null);
    const [attempt, setAttempt] = useState('1');
    const [image, setImage] = useState(1);
    const [thinking, setThinking] = useState(false);
    const [lock, setLock] = useState(false);
    
    const { getTime, start, stop, reset } = useTimer();

    const [wisySpeaking, setWisySpeaking] = useState(false)

    const isActive = useRef(true);
                                
    const playVoice = async (sound) => {
        if (!isActive.current) return
        try {
            setWisySpeaking(true)
            await playSound(sound);
        } catch (error) {
            console.error("Ошибка при воспроизведении звука:", error);
        } finally {
            setText(null);
            setWisySpeaking(false);
            setLock(false);
        }
    };

    const { clicked } = useIntroSequence({ data, tutorialShow, tutorials, introText, introAudio, level, introTaskIndex, setText, setWisySpeaking, setLock });

    useEffect(() => {
        isActive.current = true;
        start();
                      
        return () => {
            isActive.current = false;
            reset();
        };
    }, [])

    const vibrate = () => {
        Vibration.vibrate(500);
    };

    const correctAnswer = async(hint, stars, voice, old_stars, success_phrase, success_phrase_sound) => {
        if (!isActive.current) return
        
        reset();
        if (isFromAttributes) {
            // store.loadCategories();
        } else {
            onCompleteTask(subCollectionId, data?.next_task_id)
        }
        setImage(2)
        setText(hint)
        playSound(gameStore.sounds.correct ?? require('../../../assets/ok.mp3'), true, false, true)

        try {
            setWisySpeaking(true)
            await playSound(voice)
            setText(success_phrase);
            await playSound(success_phrase_sound);
        } catch (error) {
            console.log(error)
        } finally {
            setText(null);
            setWisySpeaking(false);
            setTimeout(() => {
                setStars(stars);
                setAttempt('1')
                setEarnedStars(stars - old_stars)
                setText(hint)
                setLevel(prev => prev + 1)
                setImage(1)
                setLock(false)
            }, 1500);
        }
    };

    const incorrectAnswer = async(hint, voice) => {
        if (!isActive.current) return
        playSound(gameStore.sounds.wrong ?? require('../../../assets/notok.mp3'), true, false, true)
        start();
        setText(hint);
        playVoice(voice)
        setAttempt('2'); 
    };

    const incorrectAnswerToNext = async(hint, stars, voice, old_stars) => {
        if (!isActive.current) return
        reset();
        if (isFromAttributes) {
            // store.loadCategories();
        } else {
            onCompleteTask(subCollectionId, data.next_task_id)
        }
        vibrate()
        setText(hint)
        try {

        playSound(gameStore.sounds.wrong ?? require('../../../assets/notok.mp3'), true, false, true)
        setWisySpeaking(true)
        const speech = await GetSpeeches('no_more_hints')   
        setText(speech.data?.data[0]?.text);
        await playSound(speech?.data?.data[0]?.audio);
        
            
        } catch (error) {
            console.log(error)
        } finally {
            setText(null);
            setWisySpeaking(false);
            setTimeout(() => {
                setStars(stars);
                setAttempt('1')
                setEarnedStars(stars - old_stars)
                setText(hint)
                setLevel(prev => prev + 1)
                setImage(1)
                setLock(false)
            }, 1500);
        }
    };

    const sendAnswer = async (uri) => {
        try {
            if (!isActive.current) return;
    
            const lead_time = getTime();
            stop();
            setThinking(true);
            setLock(true);
    
            const requestStatus = await AnswerVoiceTask(
                data.id,
                attempt,
                `${store.playingChildId.id}`,
                lead_time,
                uri
            );
    
            return requestStatus.data;
    
        } catch (error) {
            setLock(false);
    
            const message =
                error?.response?.data?.message || // axios ошибки от сервера
                error?.message ||                 // сетевые ошибки или JS-исключения
                'Произошла ошибка. Попробуйте снова';
    
            setText(message);

            setTimeout(() => {
                setText(null);
            }, 2000);
        } finally {
            setThinking(false);
        }
    };

    return (
        <View style={{ width: '100%', height: '100%', justifyContent: 'center', alignItems: 'center'}}>
            
            {tutorialShow && tutorials?.length > 0 && (
                <TutorialOverlay tutorials={tutorials} />
            )}

            {data && (!tutorialShow || tutorials?.length == 0 || isFromAttributes) && <TaskComponent image={image === 1? data.content?.placeholder_image?.url : data.content?.image?.url} successImage={image}/>}
                
            <OverlayHint visible={store.isBlacked}>
                <WisyHint text={text} thinking={thinking} wisySpeaking={wisySpeaking} />
            </OverlayHint>

            {!store?.isBlacked && (
                <WisyHint text={text} thinking={thinking} wisySpeaking={wisySpeaking} />
            )}

            {(!tutorialShow || tutorials?.length == 0 || isFromAttributes) && <View style={{position: 'absolute', bottom: 0, right: 0}}>
                {!lock && <MicroAnimation clicked={clicked} correctAnswer={correctAnswer} incorrectAnswerToNext={incorrectAnswerToNext} incorrectAnswer={incorrectAnswer} setText={setText} sendAnswer={sendAnswer}/>}
            </View>}     

            <SkipButton visible={tutorialShow && tutorials?.length > 0} showPaw={store?.isFirstOpening}
                onSkip={() => {
                    if (store.isFirstOpening) {
                        store.setIsFirstOpening(false)
                    }
                    setTutorialShow(false)
                }}
            />

        </View>                                                                                                                                                                             
    );
}

export default Game1Screen;